type Account struct{ Balance int64 }

func (a Account) Zero()  { a.Balance = 0 }   // value receiver
func (a *Account) Drain() { a.Balance = 0 }   // pointer receiver

func main() {
    acc := Account{Balance: 100}
    acc.Zero()                      // step 1
    fmt.Println(acc.Balance)        // Q1

    accs := []Account{{Balance: 10}, {Balance: 20}}
    for _, a := range accs { a.Balance = 50 }   // step 2
    fmt.Println(accs[0].Balance)    // Q2

    acc.Drain()                     // step 3
    fmt.Println(acc.Balance)        // Q3
}

Q1: what does acc.Balance print after Zero()?
Q2: what does accs[0].Balance print after the range loop?
Q3: what does acc.Balance print after Drain()?

