package metrics

import "sync"

type Sample struct {
	Name  string
	Value float64
}

type Registry struct {
	mu      sync.Mutex
	samples []Sample
	byName  map[string]int
}

func NewRegistry() *Registry {
	return &Registry{}
}

func (r *Registry) Add(s Sample) {
	r.mu.Lock()
	defer r.mu.Unlock()
	r.samples = append(r.samples, s)
	r.byName[s.Name]++
}

func (r *Registry) Scale(f float64) {
	r.mu.Lock()
	defer r.mu.Unlock()
	for _, s := range r.samples {
		s.Value *= f
	}
}

func (r *Registry) Snapshot() []Sample {
	r.mu.Lock()
	defer r.mu.Unlock()
	return r.samples
}
